-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('taking-criticism-in-stride', 'Taking Criticism in Stride', 'For anyone who replays every critical comment for days or bristles before the other person has finished. Each day is one small practice in hearing feedback calmly, keeping what is useful, and letting the rest go.', 'Confidence', 365, array['Self-Esteem', 'Resilience', 'Work']::text[], 1, '2026-09-30T17:00:00+00:00'::timestamptz),
  ('caring-for-someone-without-losing-yourself', 'Caring for Someone Without Losing Yourself', 'For anyone looking after a parent, partner, child or friend who needs a lot of help. Each day is one small way to keep a little of your own life, rest and support alive while you care for them.', 'Caregiving', 365, array['Caregiving', 'Self-Care', 'Boundaries']::text[], 1, '2026-09-30T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('taking-criticism-in-stride', 'caring-for-someone-without-losing-yourself');

